    println!("猜一个整数，稍后将读取你的答案。");
}

fn main() {
    let mut guess = String::new();
    guess.push_str("18");
    println!("当前文本：{}", guess);
    guess.clear();
    println!("清空后：{}", guess);
}

fn main() {
    let read: Result<usize, &str> = Ok(3);
    match read {
        Ok(bytes) => println!("读入 {} 字节", bytes),
        Err(message) => println!("读取失败：{}", message),
    }
}

fn main() {
    let guess = String::from("23");
    let turn = 2;
    println!("第 {} 轮，输入 {}", turn, guess);
    println!("{{{} }}", guess);
}

fn main() {
    let mut guess = String::new();
    std::io::stdin().read_line(&mut guess).unwrap();
    print!("收到：{}", guess);
}

use rand::Rng;
fn main() {
    // 配套依赖 rand 0.5；上界 101 不包含在内
    let secret: i32 = rand::thread_rng().gen_range(1, 101);
    println!("目标处于 1 到 100：{}", secret);
}

use std::cmp::Ordering;
fn main() {
    let guess: i32 = 28;
    let secret: i32 = 35;
    match guess.cmp(&secret) {
        Ordering::Less => println!("偏小"),
        Ordering::Equal => println!("猜中"),
        Ordering::Greater => println!("偏大"),
    }
}

fn main() {
    let mut guess = 1;
    loop {
        if guess == 3 {
            println!("猜中");
            break;
        }
        guess = guess + 1;
    }
    println!("游戏结束");
}

fn main() {
    let text = "abc";
    let number: i32 = match text.trim().parse() {
        Ok(value) => value,
        Err(_) => {
            println!("请输入整数");
            return;
        }
    };
    println!("有效数字 {}", number);
}

fn main() {
    let target = 17;
    let guess = 17;
    if guess < target {
        println!("偏小");
    } else if guess > target {
        println!("偏大");
    } else {
        println!("猜中");
    }
}
